import { Tripwire } from "./tripwire.mjs";

/**
 * Builds a client from environment variables, so command-line adapters need no code:
 *   TRIPWIRE_URL, TRIPWIRE_AUTH0_DOMAIN, TRIPWIRE_AUDIENCE, TRIPWIRE_CLIENT_ID, TRIPWIRE_CLIENT_SECRET,
 *   TRIPWIRE_AGENT_NAME (optional), TRIPWIRE_FAIL_MODE = closed | allowlist | open (default closed),
 *   TRIPWIRE_OFFLINE_ALLOW = comma-separated action types allowed while Tripwire is unreachable,
 *   TRIPWIRE_TOKEN_URL (optional override).
 */
export function tripwireFromEnv(env = process.env, overrides = {}) {
  return new Tripwire({
    baseUrl: env.TRIPWIRE_URL,
    auth0Domain: env.TRIPWIRE_AUTH0_DOMAIN,
    tokenUrl: env.TRIPWIRE_TOKEN_URL || undefined,
    audience: env.TRIPWIRE_AUDIENCE,
    clientId: env.TRIPWIRE_CLIENT_ID,
    clientSecret: env.TRIPWIRE_CLIENT_SECRET,
    agentName: env.TRIPWIRE_AGENT_NAME,
    failMode: env.TRIPWIRE_FAIL_MODE || "closed",
    offlineAllow: (env.TRIPWIRE_OFFLINE_ALLOW ?? "").split(",").map((s) => s.trim()).filter(Boolean),
    ...overrides,
  });
}

// Wraps agent tools so every call goes through Tripwire first. No framework dependency.
//
//   import { wrapTools } from "@tripwire/sdk/tools";
//   const tools = wrapTools(tw, { sessionId }, myTools);
//
// Works with any tool that exposes its implementation as one of these functions, called with the tool input
// as the first argument:
//   execute(input, ...)   Vercel AI SDK tools
//   func(input, ...)      LangChain JS DynamicTool and DynamicStructuredTool
//   invoke(input, ...)    plain objects and LangChain Runnables
// Accepts a single tool, an array of tools, or a record of name -> tool. The tool objects are patched in
// place, so class instances keep working.

const METHODS = ["execute", "func", "invoke"];

function describeTarget(input) {
  if (typeof input === "string") return input.slice(0, 500);
  if (input && typeof input === "object") {
    for (const k of ["command", "cmd", "path", "file_path", "url", "query", "sql", "to"]) if (typeof input[k] === "string") return input[k].slice(0, 500);
    try { return JSON.stringify(input).slice(0, 500); } catch { return undefined; }
  }
  return undefined;
}

export function wrapTool(tw, ctx, tool, name = tool?.name ?? "tool") {
  const method = METHODS.find((m) => typeof tool?.[m] === "function");
  if (!method) throw new Error(`Tripwire: cannot wrap tool "${name}": it has none of ${METHODS.join(", ")}`);
  if (tool[method].__tripwire) return tool;
  const original = tool[method];
  const wrapped = function (input, ...rest) {
    const sessionId = typeof ctx.sessionId === "function" ? ctx.sessionId() : ctx.sessionId;
    const action = {
      sessionId,
      actionType: ctx.actionType?.(name, input) ?? `tool.${name}`,
      target: ctx.target?.(name, input) ?? describeTarget(input),
      payload: ctx.payload?.(name, input) ?? { input },
    };
    return tw.guard(action, () => original.call(this ?? tool, input, ...rest), ctx.guardOptions);
  };
  wrapped.__tripwire = true;
  tool[method] = wrapped;
  return tool;
}

export function wrapTools(tw, ctx, tools) {
  if (Array.isArray(tools)) return tools.map((t) => wrapTool(tw, ctx, t));
  if (METHODS.some((m) => typeof tools?.[m] === "function")) return wrapTool(tw, ctx, tools);
  for (const [name, tool] of Object.entries(tools)) wrapTool(tw, ctx, tool, name);
  return tools;
}

#!/usr/bin/env node
// Claude Code PreToolUse hook: sends every tool call to Tripwire before Claude Code runs it.
//
// .claude/settings.json:
//   { "hooks": { "PreToolUse": [ { "matcher": ".*", "hooks": [
//       { "type": "command", "command": "node sdk/adapters/claude-code-hook.mjs", "timeout": 600 } ] } ] } }
//
// Configure with the TRIPWIRE_* environment variables (see sdk/env.mjs). Low-risk calls pass through to Claude
// Code's normal permission flow untouched. Held calls wait for a human (keep "timeout" high enough, in seconds).
// Denied, timed-out or (in fail-closed mode) unreachable calls are blocked with a reason Claude can read.
// TRIPWIRE_HOOK_SKIP = comma-separated tool names to skip (for example Read,Glob,Grep).

import { tripwireFromEnv } from "../env.mjs";
import { TripwireDenied, TripwireUnavailable } from "../tripwire.mjs";

const MAX_WAIT_MS = Number(process.env.TRIPWIRE_HOOK_WAIT_SECONDS || 540) * 1000;

function block(reason) {
  process.stdout.write(JSON.stringify({ hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: reason } }));
  process.exit(0);
}

let raw = "";
for await (const chunk of process.stdin) raw += chunk;
let input;
try {
  input = JSON.parse(raw);
} catch {
  block("Tripwire hook could not read the tool call.");
}

const skip = (process.env.TRIPWIRE_HOOK_SKIP ?? "").split(",").map((s) => s.trim()).filter(Boolean);
if (skip.includes(input.tool_name)) process.exit(0);

let tw;
try {
  tw = tripwireFromEnv(process.env, { agentName: process.env.TRIPWIRE_AGENT_NAME || "claude-code" });
} catch (err) {
  block(`Tripwire is not configured: ${err.message}`);
}

const toolInput = input.tool_input ?? {};
const target = toolInput.command ?? toolInput.file_path ?? toolInput.url ?? toolInput.pattern ?? undefined;

try {
  await tw.guard(
    {
      sessionId: input.session_id ?? "claude-code",
      actionType: `claude.${input.tool_name}`,
      target: typeof target === "string" ? target.slice(0, 500) : undefined,
      payload: { input: toolInput, cwd: input.cwd },
    },
    () => undefined,
    { timeoutMs: MAX_WAIT_MS },
  );
  process.exit(0); // allowed: let Claude Code's own permission flow continue
} catch (err) {
  if (err instanceof TripwireDenied) block(`Blocked by Tripwire: ${err.message}`);
  if (err instanceof TripwireUnavailable) block(`Tripwire is unreachable and the safety mode is "${tw.failMode}", so this action is blocked.`);
  block(`Tripwire error: ${err.message}`);
}

#!/usr/bin/env node
// MCP proxy: sits between an MCP client and any stdio MCP server and sends every tools/call to Tripwire first.
// The client and the server need no changes.
//
//   node sdk/adapters/mcp-proxy.mjs -- npx -y @modelcontextprotocol/server-filesystem /work
//
// In the client's MCP config, replace the server command with the line above. Configure with TRIPWIRE_* variables
// (see sdk/env.mjs). Blocked calls return a normal tool error the model can read. Every other message passes
// through untouched. MCP stdio framing is one JSON message per line.

import { spawn } from "node:child_process";
import { createInterface } from "node:readline";
import { tripwireFromEnv } from "../env.mjs";
import { TripwireDenied } from "../tripwire.mjs";

const sep = process.argv.indexOf("--");
if (sep === -1 || sep === process.argv.length - 1) {
  console.error("usage: mcp-proxy.mjs -- <server command> [args...]");
  process.exit(2);
}
const [cmd, ...args] = process.argv.slice(sep + 1);
const tw = tripwireFromEnv(process.env, { agentName: process.env.TRIPWIRE_AGENT_NAME || `mcp:${cmd}` });
const sessionId = process.env.TRIPWIRE_SESSION_ID || `mcp-${process.pid}`;

const child = spawn(cmd, args, { stdio: ["pipe", "pipe", "inherit"], shell: process.platform === "win32" });
child.on("exit", (code) => process.exit(code ?? 0));
child.on("error", (err) => {
  console.error(`mcp-proxy: cannot start ${cmd}: ${err.message}`);
  process.exit(1);
});

const toClient = (msg) => process.stdout.write(JSON.stringify(msg) + "\n");
const toServer = (msg) => child.stdin.write(JSON.stringify(msg) + "\n");
createInterface({ input: child.stdout }).on("line", (line) => process.stdout.write(line + "\n"));

function refuse(id, text) {
  toClient({ jsonrpc: "2.0", id, result: { isError: true, content: [{ type: "text", text }] } });
}

async function handleToolCall(msg) {
  const { name, arguments: toolArgs } = msg.params ?? {};
  const target = toolArgs?.command ?? toolArgs?.path ?? toolArgs?.url ?? toolArgs?.query ?? undefined;
  try {
    await tw.guard(
      { sessionId, actionType: `mcp.${name}`, target: typeof target === "string" ? target.slice(0, 500) : undefined, payload: { arguments: toolArgs } },
      () => toServer(msg),
    );
  } catch (err) {
    refuse(msg.id, err instanceof TripwireDenied ? `Blocked by Tripwire: ${err.message}` : `Blocked: Tripwire could not approve this call (${err.message})`);
  }
}

createInterface({ input: process.stdin }).on("line", (line) => {
  let msg;
  try {
    msg = JSON.parse(line);
  } catch {
    return child.stdin.write(line + "\n");
  }
  if (msg?.method === "tools/call" && msg.id !== undefined) handleToolCall(msg);
  else child.stdin.write(line + "\n");
});
process.stdin.on("end", () => child.stdin.end());

export type FailMode = "closed" | "allowlist" | "open";

export interface TripwireOptions {
  baseUrl: string;
  auth0Domain?: string;
  /** Overrides the Auth0 token endpoint (testing, custom domains). */
  tokenUrl?: string;
  audience: string;
  clientId: string;
  clientSecret: string;
  agentName?: string;
  /** What to do when Tripwire cannot be reached. Default "closed". */
  failMode?: FailMode;
  /** Action types allowed while Tripwire is unreachable when failMode is "allowlist". */
  offlineAllow?: (string | RegExp)[];
  /** Per-request timeout in ms. Default 10000. */
  timeoutMs?: number;
  /** Retries for network errors, 5xx and 429. Default 2. */
  retries?: number;
  onFailMode?: (info: { action: Action; mode: FailMode; allowed: boolean; error: Error }) => void;
  fetchImpl?: typeof fetch;
}

export interface Action {
  sessionId: string;
  actionType: string;
  target?: string;
  payload?: Record<string, unknown>;
}

export interface RiskFactor {
  kind: "rule" | "model" | "baseline" | "history" | "policy";
  label: string;
  score?: number;
  delta?: number;
}

export interface Risk {
  score: number;
  level: "low" | "medium" | "high" | "critical";
  reason: string;
  source: string;
  factors: RiskFactor[];
}

export interface ReportResult {
  event_id: string;
  time: string;
  status: "allowed" | "pending" | "denied";
  risk: Risk;
}

export interface Decision {
  status: string;
  proceed: boolean;
  event_id?: string;
}

export interface GuardOptions {
  failMode?: FailMode;
  timeoutMs?: number;
  onReport?: (r: ReportResult) => void;
  onWait?: (d: Decision) => void;
}

export class TripwireDenied extends Error {
  decision: unknown;
}
export class TripwireUnavailable extends Error {}
export class TripwireError extends Error {
  status: number;
}

export class Tripwire {
  constructor(options: TripwireOptions);
  report(action: Action): Promise<ReportResult>;
  waitForDecision(eventId: string, opts?: { timeoutMs?: number; onWait?: (d: Decision) => void }): Promise<Decision>;
  guard<T>(action: Action, fn: (r: Partial<ReportResult> & { offline?: boolean }) => T | Promise<T>, opts?: GuardOptions): Promise<T>;
}

import type { Tripwire, GuardOptions } from "../tripwire.mjs";

export interface WrapContext {
  sessionId: string | (() => string);
  actionType?: (toolName: string, input: unknown) => string;
  target?: (toolName: string, input: unknown) => string | undefined;
  payload?: (toolName: string, input: unknown) => Record<string, unknown>;
  guardOptions?: GuardOptions;
}

export function wrapTool<T>(tw: Tripwire, ctx: WrapContext, tool: T, name?: string): T;
export function wrapTools<T>(tw: Tripwire, ctx: WrapContext, tools: T): T;

