/**
 * Auth0 Post-Login Action: require MFA when Tripwire asks for step-up.
 *
 * Setup (Auth0 dashboard):
 *  1. Security > Multi-factor Auth: enable at least one factor (e.g. One-time Password or Guardian push).
 *     Leave the MFA policy on "Never" so normal logins skip it.
 *  2. Actions > Library > Create Action > "Login / Post Login", paste this file, Deploy.
 *  3. Actions > Triggers > post-login: drag the Action into the flow, Apply.
 *
 * Tripwire sends acr_values=<multi-factor policy> when approving a risky action.
 * After MFA, Auth0 puts amr: ["mfa"] in the ID token, which the app checks.
 */
const MFA_ACR = "http://schemas.openid.net/pape/policies/2007/06/multi-factor";

exports.onExecutePostLogin = async (event, api) => {
  const requested = (event.transaction && event.transaction.acr_values) || [];
  if (requested.includes(MFA_ACR)) {
    api.multifactor.enable("any", { allowRememberBrowser: false });
  }
};
import { Auth0Client, filterDefaultIdTokenClaims } from "@auth0/nextjs-auth0/server";
import { decodeJwt } from "jose";

export const auth0 = new Auth0Client({
  // Keep the claims step-up MFA needs (`amr`, `auth_time`) next to the default profile claims.
  // The SDK has already verified the ID token by the time this runs.
  async beforeSessionSaved(session, idToken) {
    const claims = idToken ? decodeJwt(idToken) : {};
    return {
      ...session,
      user: {
        ...filterDefaultIdTokenClaims(session.user),
        amr: Array.isArray(claims.amr) ? claims.amr : [],
        auth_time: typeof claims.auth_time === "number" ? claims.auth_time : undefined,
      },
    };
  },
});
5:Agents send every action they take to Tripwire. Gemini scores each action's risk. Risky actions pause until a human approves them with MFA. Every event is logged and charted live.
11:| Login, agent tokens, step-up MFA | Auth0 | Humans sign in; agents get M2M tokens; approvals require MFA |
19:- `/approvals`: queue of held actions; approve with MFA or deny
61:Agents report every action to Tripwire before running it. Low-risk actions run at once, risky ones wait for a human with MFA, denied ones never run.
105:Every action stores the factors behind its score, shown as "Why this score" on Approvals and on each incident. Policies that loosen protection (`allow`, or turning off/deleting `deny` and `require_approval`) need a fresh MFA check.

