        amr: Array.isArray(claims.amr) ? claims.amr : [],
        auth_time: typeof claims.auth_time === "number" ? claims.auth_time : undefined,
      },
    };
  },
});
5:Agents send every action they take to Tripwire. Gemini scores each action's risk. Risky actions pause until a human approves them with MFA. Every event is logged and charted live.
11:| Login, agent tokens, step-up MFA | Auth0 | Humans sign in; agents get M2M tokens; approvals require MFA |
19:- `/approvals`: queue of held actions; approve with MFA or deny
61:Agents report every action to Tripwire before running it. Low-risk actions run at once, risky ones wait for a human with MFA, denied ones never run.
105:Every action stores the factors behind its score, shown as "Why this score" on Approvals and on each incident. Policies that loosen protection (`allow`, or turning off/deleting `deny` and `require_approval`) need a fresh MFA check.

